import math

def phi(n):
    """Calculates Euler's totient function phi(n)."""
    result = n
    p = 2
    while p * p <= n:
        if n % p == 0:
            while n % p == 0:
                n //= p
            result -= result // p
        p += 1
    if n > 1:
        result -= result // n
    return result

def order_mod(a, n):
    """
    Calculates the multiplicative order of a modulo n.
    Assumes gcd(a, n) = 1.
    """
    if math.gcd(a, n) != 1:
        # This should not happen based on problem constraints (m not divisible by 3)
        return None

    # Euler's totient theorem guarantees the order divides phi(n)
    phi_n = phi(n)

    # Iterate through divisors of phi_n
    for k in range(1, phi_n + 1):
        if phi_n % k == 0:
            if pow(a, k, n) == 1:
                return k
    return phi_n # Should be found earlier, but as a fallback

def calculate_C_m(m):
    """
    Calculates the total number of cycles C(m) for the permutation x -> 3x mod m.
    C(m) = sum_{j|m, j>1} phi(j) / ord_j(3)
    """
    if m <= 1:
        return 0

    divisors = []
    for i in range(1, int(math.sqrt(m)) + 1):
        if m % i == 0:
            divisors.append(i)
            if i * i != m:
                divisors.append(m // i)

    # Sum over j|m where j > 1
    C_m = 0
    for j in divisors:
        if j > 1:
            # Since m is not divisible by 3, j is not divisible by 3, so gcd(3, j) = 1
            ord_j_3 = order_mod(3, j)
            C_m += phi(j) // ord_j_3

    return C_m

# --- Main execution ---
M_START = 2
M_END = 100
results = {}
odd_C_m = []

print("--- Results for m < 100 ---")
for m in range(M_START, M_END):
    if m % 3 != 0:
        C_m = calculate_C_m(m)
        results[m] = C_m

        if C_m % 2 != 0:
            odd_C_m.append((m, C_m))

        print(f"m={m:2}: C(m) = {C_m}")

print("\n--- Summary of m where C(m) is odd ---")
if odd_C_m:
